use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm;

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let system = "You are a customer-support assistant. Answer the user's \
                      question. You may use the `lookup` tool to search the \
                      knowledge base when you need more information.";

        // Build the initial prompt from the attenuated context. `question` is
        // bounded (requires len <= 512) but still untrusted free text; it is
        // only ever used as model material here, never as authority.
        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push_str("\nQuestion: ");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\nKnowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        // Tool-orchestration loop. The model either answers (text) or asks for a
        // tool (call). The only tool this node can invoke is `lookup`, backed by
        // the read-only knowledge-base handle.
        const MAX_ROUNDS: u32 = 8;
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(system, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nTool `lookup` results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\":\n");
                        if results.is_empty() {
                            prompt.push_str("(no results)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        return ResponseResult::Error(LlmError {
                            message: format!("tool not available: {}", req.tool),
                        });
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool orchestration did not converge".to_string(),
        })
    }
}

